import{z as m,x as B,o as l,c as p,q as r,j as o,D as t,d as e,s as i,S as E,b as s}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"贝尔曼方程","description":"","frontmatter":{"title":"贝尔曼方程","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bellman-dp.md","filePath":"econ/bellman-dp.md","lastUpdated":1791063341000}'),d={name:"econ/bellman-dp.md"};function c(A,a,u,h,g,k){const n=B("Mermaid");return l(),p("div",null,[a[2]||(a[2]=r('<h1 id="贝尔曼方程" tabindex="-1">贝尔曼方程 <a class="header-anchor" href="#贝尔曼方程" aria-label="Permalink to &quot;贝尔曼方程&quot;">​</a></h1><div class="epigraph"><p>最优值是今天的回报加上贴现后的续值；状态足够时，序列问题塌成函数方程。</p><footer>—— Bellman, Dynamic Programming, 1957；Stokey and Lucas with Prescott, Recursive Methods in Economic Dynamics, 1989</footer></div><p><a href="/econ/backus-smith">上一课</a>把开放宏观主干收在 Backus–Smith 之谜：完全市场要求实际汇率跟踪相对消费，数据里却锁不上，逐期检查欧拉到此已经用尽。本课是「动态宏观与异质性」的第一课，换装置：把序列问题写成<strong>一般递归</strong>——状态、控制、转移、值函数。方程与不动点的论证是数学基础课<a href="/econ/bellman-equation">贝尔曼方程</a>的成品，本课只取用；后课默认已经有这条方程，不再每次从 Ramsey 序列重写。不重解 HJB，不进限价簿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Samuelson 的 \\(V_t(W)\\) 是财富上的贝尔曼，状态几乎是标量。宏观一旦有资本、劳动、外生冲击，序列问题是 \\(\\max\\mathrm{E}\\sum_t\\beta^t u(c_t)\\) 受资源与技术约束，直接写无穷序列既难算也难看清政策是状态的函数。写成函数方程就是 \\(V(s)=\\max_{a\\in\\Gamma(s)}\\{r(s,a)+\\beta\\mathrm{E}[V(s&#39;)\\mid s,a]\\}\\)，其中 \\(s\\) 为状态，\\(a\\) 为控制，\\(\\Gamma\\) 为可行集；它连同 Blackwell 压缩与唯一不动点的论证，<a href="/econ/bellman-equation">贝尔曼方程</a>已经一次证完，本课只取用。缺口不是再推消费欧拉，而是：动态宏观的对象是这个函数方程的解 \\(V\\) 与政策 \\(a=g(s)\\)，不是一条事先写死的时间路径。</p><p><span class="marginnote">Stokey–Lucas–Prescott 把压缩映射、单调性、凹性写成宏观可用的许可证。Blackwell 充分条件保证 \\(T\\) 是折扣压缩。本课用它们，不重写泛函分析。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先选状态：凡是影响可行集或回报、且按已知转移走的变量都进 \\(s\\)。增长模型里状态向量是 \\((k,z)\\)：\\(k\\) 是昨天投资留下的资本存量，\\(z\\) 是按马尔可夫转移的生产率；不随时间变的偏好与技术参数不必进状态。控制是 \\(c\\) 或投资。用法在解出来的<strong>策略函数</strong> \\(g\\)：\\(g_k(k,z)\\) 给出下一期资本，\\(g_c(k,z)\\) 给出消费。稳态读作 \\(g\\) 的不动点，\\(g_k(k^*,\\bar z)=k^*\\)；从任何初值反复代 \\(g_k\\) 就得到转移路径，不再对整条 \\(\\{k_t\\}\\) 做变分。冲击下同一张 \\(g\\) 对每个 \\(z\\) 各有一页，模拟即抽样 \\(z\\) 的历史并迭代。确定性下包络给出欧拉；随机下给出随机欧拉。横截与泡沫下一课才钉。</p><p><span class="marginnote">数字实例：若生产率 \\(z\\) 只取 \\(\\{0.9,\\,1.0,\\,1.1\\}\\) 三档并按马尔可夫链转移，策略函数 \\(g_k\\) 就是一张「\\(k\\) 连续、\\(z\\) 三行」的表；模拟一千期，等于抽一千次 \\(z\\)、每次查一次表，不需要重新求解任何优化问题。</span></p>',9)),(l(),o(E,null,{default:t(()=>[i(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEQ%5B%22%E5%BA%8F%E5%88%97%E9%97%AE%E9%A2%98%22%5D%20--%3E%20ST%5B%22%E9%80%89%E7%8A%B6%E6%80%81%20s%22%5D%0A%20%20ST%20--%3E%20BE%5B%22V%20%3D%20T(V)%22%5D%0A%20%20BE%20--%3E%20POL%5B%22%E6%94%BF%E7%AD%96%20a%20%3D%20g(s)%22%5D%0A%20%20POL%20--%3E%20PATH%5B%22%E6%B2%BF%E8%BD%AC%E7%A7%BB%E8%B5%B0%E5%87%BA%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("p",null,"与上一课的分工：Backus–Smith 收在开放约束下欧拉失灵的实证僵局；本课回到总量装置，示范同一方程如何接到资本积累与增长。资产菜单若再出现，只引用欧拉的资产形式，不重写组合课的短视定理。",-1)),a[4]||(a[4]=s("h2",{id:"机制",tabindex:"-1"},[e("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=s("p",null,[e("机制是"),s("strong",null,"状态充分统计"),e("。昨天的决策只通过今天的 \\(s\\) 影响明天，历史不必进自变量。政策因此是函数 \\(g\\)，加总与估计才能写成递归均衡：价格是 \\(s\\) 的函数，家庭的 \\(V\\) 把价格函数当给定，再出清。代表性个体时 \\(s\\) 是总量；异质时个人状态与分布一起走——那是 "),s("a",{href:"/econ/bewley-aiyagari"},"Bewley"),e(" 的缺口，本课先把算子立住。")],-1)),(l(),o(E,null,{default:t(()=>[i(n,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20H1%5B%22%E5%8E%86%E5%8F%B2%20A%EF%BC%9A%E4%B8%80%E8%B7%AF%E9%AB%98%E6%B6%88%E8%B4%B9%22%5D%20--%3E%20S%5B%22%E4%BB%8A%E5%A4%A9%E7%8A%B6%E6%80%81%20(k%2C%20z)%22%5D%0A%20%20H2%5B%22%E5%8E%86%E5%8F%B2%20B%EF%BC%9A%E4%B8%80%E8%B7%AF%E7%9C%81%E7%9D%80%E8%8A%B1%22%5D%20--%3E%20S%0A%20%20S%20--%3E%20G%5B%22%E6%9F%A5%E7%AD%96%E7%95%A5%E5%87%BD%E6%95%B0%20g%22%5D%0A%20%20G%20--%3E%20C%5B%22%E4%BB%8A%E5%A4%A9%E6%B6%88%E8%B4%B9%20c%20%3D%20g_c(k%2Cz)%22%5D%0A%20%20G%20--%3E%20K%5B%22%E6%98%8E%E5%A4%A9%E8%B5%84%E6%9C%AC%20k'%20%3D%20g_k(k%2Cz)%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>时间不一致已经在主干出现过：若未来自己会再优化且与今天目标冲突，\\(V\\) 的递归要改成博弈。本课程默认标准贴现效用，承诺问题另接。连续时间 HJB 是同一递归的扩散写法，本栏不重推伊藤。</p><p><span class="marginnote">直觉类比：状态像棋盘上的当前局面——接下来怎么下只看局面，不必知道每一步是怎么走出来的。但若状态选漏了一格（比如漏掉债务期限），「局面」就不足以决定下一步，方程从源头就错了。</span></p><p><span class="marginnote">Lucas 树的 \\(p(y)\\) 也是递归：价格是果实状态的函数。本课不重写树，只提醒：定价函数与值函数是同一装置的两个实例。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给算法（下一课 VFI/PI），不把欧拉当唯一一阶条件（再下一课才把横截补上）。也不把贝尔曼写成「宏观就是动态规划」的口号：没有正确的状态，方程是错的；没有压缩或有界性，唯一性不必有。无限维分布作为状态时，压缩论证更脆，留给 Krusell–Smith。</p><p><span class="marginnote">为什么重要：本课只立方程、不解方程，\\(g\\) 的存在性靠压缩不动点保证。若跳过这一步直接拿 \\(g\\) 做比较静态或模拟，等于把一个尚未证明存在的函数当成了工具。</span></p><p>后课默认：动态宏观先写 \\(V=T(V)\\) 与 \\(g(s)\\)；序列形式只在需要横截或变分时展开。组合短视、两基金、FTAP 属于信息与无套利课程，本栏不重写。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>贝尔曼把序列问题收成状态上的函数方程；\\(V\\) 与政策 \\(g\\) 是后课的公共对象。</li><li>状态必须充分；算子在折扣与有界回报下常是压缩。</li><li>本课从开放宏观的僵局交接：交付的是状态向量与策略函数，不再讲菜单。</li><li>出处：Bellman 1957；Stokey, Lucas and Prescott, <em>Recursive Methods</em>, 1989。</li></ul>',9))])}const b=m(d,[["render",c]]);export{D as __pageData,b as default};
